CREATE TABLE IF NOT EXISTS customers (customer_id VARCHAR(32) PRIMARY KEY, gender VARCHAR(20), senior_citizen SMALLINT, partner VARCHAR(10), dependents VARCHAR(10), tenure SMALLINT, phone_service VARCHAR(30), multiple_lines VARCHAR(30), internet_service VARCHAR(30), online_security VARCHAR(30), online_backup VARCHAR(30), device_protection VARCHAR(30), tech_support VARCHAR(30), streaming_tv VARCHAR(30), streaming_movies VARCHAR(30), contract VARCHAR(40), paperless_billing VARCHAR(10), payment_method VARCHAR(60), monthly_charges NUMERIC(12,2), total_charges NUMERIC(12,2), churn VARCHAR(10), churn_flag SMALLINT, total_charges_missing SMALLINT);
CREATE INDEX IF NOT EXISTS ix_customers_churn ON customers(churn_flag);
CREATE INDEX IF NOT EXISTS ix_customers_contract ON customers(contract);
